import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { getClaimsByFinderId, getReportedItemsByUserId } from "@/lib/mock-data";
import { ReportedItemsList } from "@/components/reported-items-list";
import { ClaimsList } from "@/components/claims-list";

export default async function DashboardPage() {
    const currentUserId = 'user-2'; 
    
    const reportedItems = await getReportedItemsByUserId(currentUserId);
    const claimsOnMyItems = await getClaimsByFinderId(currentUserId);

    return (
        <div className="container mx-auto max-w-7xl px-4 py-8">
            <div className="space-y-4 mb-8">
                <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
                <p className="text-muted-foreground">
                    Manage your reported items and review claims.
                </p>
            </div>

            <Tabs defaultValue="reported-items">
                <TabsList className="grid w-full grid-cols-2 sm:w-[400px]">
                    <TabsTrigger value="reported-items">My Reported Items</TabsTrigger>
                    <TabsTrigger value="claims">Claims on My Items</TabsTrigger>
                </TabsList>
                <TabsContent value="reported-items">
                   <ReportedItemsList items={reportedItems} />
                </TabsContent>
                <TabsContent value="claims">
                    <ClaimsList claims={claimsOnMyItems} />
                </TabsContent>
            </Tabs>
        </div>
    );
}
