export const getItems = async () => {
  return mockItems;
};

export const getItemById = async (id: string) => {
  return mockItems.find(item => item.id === id);
};

export const getClaimsByFinderId = async (finderId: string) => {
    const foundItemIds = mockItems.filter(item => item.reportedBy === finderId && item.status === 'found').map(item => item.id);
    return mockClaims.filter(claim => foundItemIds.includes(claim.itemId));
}

export const getReportedItemsByUserId = async (userId: string) => {
    return mockItems.filter(item => item.reportedBy === userId);
}

export const getUserById = async (userId: string) => {
    return mockUsers.find(user => user.id === userId);
}
